/**
 * Response shapes of the audited NestJS API, transcribed from
 * `openapi/openapi.json` (generated by `pnpm openapi:generate`).
 * They are intentionally kept separate from the storefront domain types so a
 * change in the API contract is visible in one place.
 */

export interface ApiCategoryRef {
  id: string;
  name: string;
  slug: string;
}

export interface ApiBrandRef {
  id: string;
  name: string;
  slug: string;
}

export interface ApiImage {
  url: string;
  altText: string | null;
  position: number;
}

export interface ApiProductSummary {
  id: string;
  name: string;
  slug: string;
  status: 'DRAFT' | 'PUBLISHED' | 'ARCHIVED';
  basePriceMinor: number;
  baseCurrency: string;
  discountBasisPoints: number;
  effectivePriceMinor: number;
  category: ApiCategoryRef;
  brand: ApiBrandRef;
  createdAt: string;
  updatedAt: string;
}

export interface ApiProductsResponse {
  items: ApiProductSummary[];
  nextCursor: string | null;
}

export interface ApiCategory extends ApiCategoryRef {
  parentId: string | null;
  position: number;
  children: ApiCategory[];
}

export interface ApiCategoriesResponse {
  categories: ApiCategory[];
}

export interface ApiBundleComponent {
  id: string;
  name: string;
  quantity: number;
}

export interface ApiBundle {
  id: string;
  name: string;
  kind: 'FIXED' | 'DYNAMIC';
  status: string;
  totalPriceMinor: number;
  currency: string;
  components: ApiBundleComponent[];
}

export interface ApiBundlesResponse {
  items: ApiBundle[];
}
